}
.zs-search-container {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  background-color: #ffffff;
  padding: 8px 0;
}
.zs-logo-link {
  display: inline-flex;
  align-items: center;
  text-decoration: none;
  flex-shrink: 0;
}
.zs-logo {
  height: 40px;
  width: auto;
  display: block;
  border: 0;
}
.zs-input-group {
  display: flex;
  flex: 1;
  min-width: 180px;
  gap: 8px;
  flex-wrap: wrap;
}
.zs-input {
  flex: 3;
  min-width: 120px;
  padding: 10px 12px;
  font-size: 1rem;
  border: 1px solid #ccc;
  border-radius: 8px;
  outline: none;
  transition: all 0.2s ease;
  background-color: #fff;
  color: #1f2d3d;
}
.zs-input:focus {
  border-color: #4a90e2;
  box-shadow: 0 0 0 3px rgba(74, 144, 226, 0.2);
}
.zs-button {
  flex: 1;
  min-width: 90px;
  padding: 10px 16px;
  font-size: 1rem;
  font-weight: 500;
  color: #fff;
  background-color: #4a90e2;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 0.2s ease;
  white-space: nowrap;
}
.zs-button:hover {
  background-color: #357abd;
}
@media (max-width: 500px) {
  .zs-search-container {
    flex-direction: column;
    align-items: stretch;
  }
  .zs-logo-link {
    justify-content: center;
  }
  .zs-input-group {
    width: 100%;
  }
}
&lt;/style&gt;

